// 1. Get the AI response and the email directly from the input data (from the form)
const aiOutput = $input.first().json.output || '';
// Here we grab the email (Adjust this if your form field has another name)
let email =  $('Book Recomendation Form').first().json['What is your email address?'] || "default_email@example.com";

let name = "reader";

// 2. Extract the name from the text before the '@' in the email
if (email && email.includes('@') && email !== "default_email@example.com") {
  let extractedName = email.split('@')[0];
  // Optional: Capitalize the first letter so it looks better in the email (e.g., "john" -> "John")
  name = extractedName.charAt(0).toUpperCase() + extractedName.slice(1);
}

// 3. The main text to process is simply the AI output (no need to clean hidden JSONs anymore)
let mainText = aiOutput.trim();

// 4. Format the Markdown text into elegant HTML
let htmlContent = mainText
  // Title of each book (📚 **Title - Author**)
  .replace(/📚 \*\*(.+?)\*\*/g, '<h3 style="color:#2c3e50; margin-top: 28px; margin-bottom: 8px; font-size: 20px; border-bottom: 2px solid #e2e8f0; padding-bottom: 4px;">📚 $1</h3>')

  // Convert custom bold text into nice subtitles
  .replace(/\*([^\*:]+):\*/g, '<strong style="color:#d97706;">$1:</strong>')
  .replace(/\*\*(.+?)\*\*/g, '<strong style="color:#1e293b;">$1</strong>')

  // Italics (Emphasis)
  .replace(/\*(.+?)\*/g, '<em style="color:#475569;">$1</em>')

  // Double line breaks converted into paragraphs
  .split('\n\n')
  .map(p => {
    let text = p.trim();
    return text ? `<p style="line-height: 1.6; color: #4a5568; margin-bottom: 12px;">${text.replace(/\n/g, '<br>')}</p>` : '';
  })
  .join('\n');

// 5. Professional Email Template (Responsive and modern)
const htmlBody = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Your Literary Recommendations</title>
</head>
<body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; background-color: #f8fafc; margin: 0; padding: 0; -webkit-font-smoothing: antialiased;">
  <div style="max-width: 600px; margin: 30px auto; background-color: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);">

    <div style="background: linear-gradient(135deg, #1e293b 0%, #0f172a 100%); padding: 40px 30px; text-align: center;">
      <h1 style="color: #ffffff; font-size: 26px; margin: 0; font-weight: 700;">Your Next Reads 📖</h1>
      <p style="color: #94a3b8; font-size: 16px; margin: 12px 0 0 0; font-style: italic;">An exclusive selection for you, ${name}</p>
    </div>

    <div style="padding: 30px 40px; background-color: #ffffff;">
      ${htmlContent}

      <div style="margin-top: 40px; text-align: center;">
        <a href="https://vanovi.design" style="display: inline-block; background-color: #3b82f6; color: #ffffff; font-weight: 600; text-decoration: none; padding: 12px 24px; border-radius: 6px; font-size: 15px;">Explore more on Vanovi</a>
      </div>
    </div>

    <div style="background-color: #f1f5f9; padding: 24px 30px; text-align: center; border-top: 1px solid #e2e8f0;">
      <p style="margin: 0; color: #64748b; font-size: 14px;">Generated with ❤️ by BookBot</p>
      <p style="margin: 6px 0 0 0; color: #94a3b8; font-size: 12px;">We hope you immensely enjoy your next literary adventure.</p>
    </div>

  </div>
</body>
</html>`;

// 6. Pass to the Send Email node
return [{
  json: {
    to: email, 
    subject: `Your next great literary adventure awaits, ${name} 📚`,
    html: htmlBody
  }
}];
